def clean_stale_history(sentence: str, report_year: int) -> bool:
    years = [int(value) for value in re.findall(r"(?:19|20)\d{2}", sentence)]
    short_years = [
        2000 + int(value)
        for value in re.findall(r"(?<!\d)(\d{2})\s*\ub144(?:\ub3c4)?", sentence)
        if int(value) <= report_year % 100
    ]
    years.extend(short_years)
    if not years or max(years) > report_year - 2:
        return False
    current_marker = re.search(
        r"\ud604\uc7ac|\ub2f9\uae30|\uc9c0\uc18d\uc801|\uc6b4\uc601\s*(?:\uc911|\ud558\uace0)|\uac1c\ubc1c\s*\uc911|\uacf5\uae09\s*\uc911",
        sentence,
    )
    return not bool(current_marker)

def document_to_text(content: bytes) -> str:
    if content[:2] != b"PK":
        message = dart_base.parse_open_dart_error(content)
        raise RuntimeError(message or "OpenDART document endpoint did not return ZIP")
    text_parts: list[str] = []
    with zipfile.ZipFile(io.BytesIO(content)) as archive:
        names = [name for name in archive.namelist() if name.lower().endswith((".xml", ".html", ".htm"))]
        for name in names:
            raw = archive.read(name)
            decoded = dart_base.decode_bytes(raw)
            root = etree.fromstring(
                decoded.encode("utf-8", errors="replace"),
                parser=etree.XMLParser(recover=True, huge_tree=True, encoding="utf-8"),
            )
            text_parts.append("\n".join(part.strip() for part in root.itertext() if part and part.strip()))
    return "\n".join(text_parts)

def stale_historical(sentence: str, report_year: int | None) -> bool:
    if not report_year:
        return False
    years = [int(value) for value in re.findall(r"(?:19|20)\d{2}", sentence)]
    if not years:
        return False
    current_language = CURRENT_LANGUAGE_RE.search(sentence)
    return max(years) <= report_year - 2 and not current_language

def stale_chronology(sentence: str, report_year: int | None) -> bool:
    if not CHRONOLOGY_RE.search(sentence):
        return False
    years = [int(value) for value in re.findall(r"(?:19|20)\d{2}", sentence)]
    if not years:
        return True
    if not report_year:
        return False
    return max(years) < report_year

def platform_is_digital(sentence: str) -> bool:
    if not PLATFORM_RE.search(sentence) or NON_DIGITAL_COLLISION_RE.search(sentence):
        return False
    return bool(PLATFORM_QUALIFIER_RE.search(sentence))

def normalized_company_tokens(corp_name: str | None) -> list[str]:
    if not corp_name:
        return []
    cleaned = re.sub(r"[()（）㈜주식회사\s]", "", str(corp_name))
    tokens = [cleaned]
    if cleaned.endswith("홀딩스"):
        tokens.append(cleaned.removesuffix("홀딩스"))
    return [token for token in tokens if len(token) >= 2]

def compile_terms(terms: Sequence[str]) -> Dict[str, re.Pattern[str]]:
    patterns: Dict[str, re.Pattern[str]] = {}
    for term in terms:
        escaped = re.escape(term).replace(r"\ ", r"\s*")
        if re.fullmatch(r"[A-Za-z0-9&.+-]+", term):
            pattern = rf"(?<![A-Za-z0-9]){escaped}(?![A-Za-z0-9])"
        else:
            pattern = escaped
        patterns[term] = re.compile(pattern, flags=re.IGNORECASE)
    return patterns

def clean_segment(segment: str) -> str:
    segment = normalize_text(segment)
    segment = re.sub(r"[◆◇●■□▶▷※]+", " ", segment)
    segment = re.sub(r"\s+", " ", segment)
    return segment.strip(" \t\r\n-;:·ㆍ")

def is_table_noise(segment: str) -> bool:
    if any(pattern.search(segment) for pattern in TABLE_NOISE_REGEX):
        return True
    if "-----------" in segment or "========" in segment:
        return True
    if segment.count("|") >= 2 or segment.count("\t") >= 2:
        return True
    digit_count = len(re.findall(r"\d", segment))
    if len(segment) and digit_count / len(segment) > 0.35:
        return True
    comma_count = segment.count(",")
    tokens = KOREAN_TOKEN_RE.findall(segment)
    if tokens and comma_count / len(tokens) > 0.35:
        return True
    if len(tokens) >= 8:
        numeric_tokens = [token for token in tokens if re.fullmatch(r"[\d,./()%+-]+", token)]
        if len(numeric_tokens) / len(tokens) > 0.35:
            return True
    return False

def is_korean_narrative_segment(segment: str) -> bool:
    if len(segment) < 25 or len(segment) > 700:
        return False
    hangul_chars = len(HANGUL_RE.findall(segment))
    if hangul_chars < 15:
        return False
    tokens = KOREAN_TOKEN_RE.findall(segment)
    if len(tokens) < 5:
        return False
    if is_table_noise(segment):
        return False
    return True

def split_korean_sentences(text: str) -> List[str]:
    text = normalize_text(text)
    text = re.sub(r"[•]+", "\n", text)
    raw_lines = [clean_segment(line) for line in text.splitlines()]
    raw_lines = [line for line in raw_lines if line]

    candidates: List[str] = []
    buffer: List[str] = []

    def flush_buffer() -> None:
        if not buffer:
            return
        combined = clean_segment(" ".join(buffer))
        buffer.clear()
        if not combined:
            return
        parts = SENTENCE_SPLIT_RE.split(combined)
        for part in parts:
            cleaned = clean_segment(part)
            if is_korean_narrative_segment(cleaned):
                candidates.append(cleaned)

    for line in raw_lines:
        if is_table_noise(line) and not match_terms(line, DIGITAL_CORE_PATTERNS):
            flush_buffer()
            continue
        buffer.append(line)
        current = clean_segment(" ".join(buffer))
        if KOREAN_END_RE.search(line) or len(current) >= 350:
            flush_buffer()
    flush_buffer()

    return candidates

def decode_bytes(raw: bytes) -> str:
    for encoding in ("utf-8-sig", "utf-8", "utf-16", "euc-kr", "cp949", "latin-1"):
        try:
            return raw.decode(encoding)
        except UnicodeDecodeError:
            continue
    return raw.decode("utf-8", errors="ignore")

def parse_open_dart_error(content: bytes) -> str:
    text = decode_bytes(content[:5000]).strip()
    try:
        root = ET.fromstring(text)
        status = root.findtext("status") or ""
        message = root.findtext("message") or ""
        if status or message:
            return f"{status} {message}".strip()
    except ET.ParseError:
        pass
    try:
        data = json.loads(text)
        status = str(data.get("status", ""))
        message = str(data.get("message", ""))
        if status or message:
            return f"{status} {message}".strip()
    except json.JSONDecodeError:
        pass
    return text[:500]

def decode_bytes(raw: bytes) -> str:
    for encoding in ("utf-8-sig", "utf-8", "utf-16", "euc-kr", "cp949", "latin-1"):
        try:
            return raw.decode(encoding)
        except UnicodeDecodeError:
            continue
    return raw.decode("utf-8", errors="ignore")

def markup_to_text(raw_text: str) -> str:
    raw_text = raw_text or ""
    if BeautifulSoup is not None:
        parser = "lxml" if lxml_html is not None else "html.parser"
        soup = BeautifulSoup(raw_text, parser)
        for tag in soup(["script", "style"]):
            tag.decompose()
        return normalize_text(soup.get_text(" "))
    if lxml_html is not None:
        try:
            root = lxml_html.fromstring(raw_text)
            return normalize_text(root.text_content())
        except Exception:
            pass
    no_tags = re.sub(r"<[^>]+>", " ", raw_text)
    return normalize_text(no_tags)

def zip_document_to_text(content: bytes) -> Tuple[str, int]:
    with zipfile.ZipFile(io.BytesIO(content)) as archive:
        names = [
            name
            for name in archive.namelist()
            if name.lower().endswith((".xml", ".html", ".htm", ".txt"))
        ]
        text_parts = []
        for name in sorted(names):
            raw = archive.read(name)
            text_parts.append(markup_to_text(decode_bytes(raw)))
    return "\n".join(text_parts), len(names)
